/**
 * Workspace containment for the pure-JS search tools.
 *
 * These tools read with plain `node:fs`, so they never pass through `ctx.fs`
 * and its sandbox. Without a guard, `path: '..'` or an absolute path lets
 * `grep` reach `dsh-home/.api-key` (the provider credential) and the bundle's
 * `rawfile/secrets.json`. This test pins the guard: inside resolves, escapes
 * are refused with the same error vocabulary as other search failures.
 *
 * Run from the payload root so `@deepseek-ai/*` imports resolve:
 *   node --test host/.../dsh-tool-fs-search-js/test/contain.test.mjs
 */
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

import { runGlob, runGrep } from '../index.js'

const CAPS = {
  globMaxResults: 100,
  grepMaxMatches: 250,
  grepMaxLineBytes: 2000,
  maxFileBytes: 20 * 1024 * 1024,
  rawOutputMaxBytes: 2e7,
  timeoutMs: 30000
}

/** A workdir with one nested hit, plus a sibling directory that must stay out of reach. */
function fixture() {
  const root = mkdtempSync(join(tmpdir(), 'dsh-contain-'))
  const ws = join(root, 'ws')
  mkdirSync(join(ws, 'sub'), { recursive: true })
  writeFileSync(join(ws, 'sub', 'a.txt'), 'TODO inside\n')
  writeFileSync(join(root, 'secret.txt'), 'sk-should-not-be-readable\n')
  const ctx = { workingDirectory: { ensure: async () => ws } }
  const exec = { agent: {}, signal: undefined }
  return { root, ws, ctx, exec }
}

test('grep finds a hit inside the workspace', async () => {
  const { ctx, exec } = fixture()
  const { matches } = await runGrep(ctx, CAPS, { pattern: 'TODO' }, exec)
  assert.equal(matches.length, 1)
  assert.equal(matches[0].path, 'sub/a.txt')
})

test('grep refuses a parent-relative path', async () => {
  const { ctx, exec } = fixture()
  await assert.rejects(
    () => runGrep(ctx, CAPS, { pattern: 'sk-', path: '..' }, exec),
    /escapes the session workspace/
  )
})

test('grep refuses an absolute path outside the workspace', async () => {
  const { ctx, exec } = fixture()
  await assert.rejects(
    () => runGrep(ctx, CAPS, { pattern: 'sk-', path: '/tmp' }, exec),
    /escapes the session workspace/
  )
})

test('grep accepts an absolute path inside the workspace', async () => {
  const { ctx, exec, ws } = fixture()
  const { matches } = await runGrep(ctx, CAPS, { pattern: 'TODO', path: join(ws, 'sub') }, exec)
  assert.equal(matches.length, 1)
})

test('glob refuses a parent-relative path', async () => {
  const { ctx, exec } = fixture()
  await assert.rejects(
    () => runGlob(ctx, CAPS, { pattern: '**/*.txt', path: '../' }, exec),
    /escapes the session workspace/
  )
})

test('glob lists files inside the workspace', async () => {
  const { ctx, exec } = fixture()
  const { paths } = await runGlob(ctx, CAPS, { pattern: '**/*.txt' }, exec)
  assert.deepEqual(paths, ['sub/a.txt'])
})
